pub struct SFrameStruct {
    pub cipher_suite: u16,
    #[cfg_attr(feature = "schemars", schemars(with = "Vec<u8>"))]
    pub base_key: crate::Bytes,
    #[cfg_attr(feature = "schemars", schemars(with = "Vec<u8>"))]
    pub kid: crate::Bytes,
}

impl SFrameStruct {
    pub const FIELD_BASE_KEY: FieldId = FieldId::new(0x1);
    pub const FIELD_CIPHER_SUITE: FieldId = FieldId::new(0x0);
    pub const FIELD_KID: FieldId = FieldId::new(0x2);

    #[must_use]
    pub fn new(cipher_suite: impl Into<u16>, base_key: impl Into<crate::Bytes>, kid: impl Into<crate::Bytes>) -> Self {
        Self {
            cipher_suite: cipher_suite.into(),
            base_key: base_key.into(),
            kid: kid.into(),
        }
    }

    pub(crate) fn decode_fields_inner(
        fields: Vec<(FieldId, AttributeValue)>,
    ) -> Result<Self, (Option<FieldId>, MatterStatus)> {
        let mut cipher_suite = None;
        let mut base_key = None;
        let mut kid = None;
        for (fid, fval) in fields {
            match fid.raw() {
                0 => {
                    if cipher_suite.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <u16>::try_from(fval)?;
                        (decoded >= 1_u16).then_some(()).ok_or(MatterStatus::ConstraintError)?;
                        cipher_suite = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                1 => {
                    if base_key.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <crate::Bytes>::try_from(fval)?;
                        (decoded.len() <= 128)
                            .then_some(())
                            .ok_or(MatterStatus::ConstraintError)?;
                        base_key = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                2 => {
                    if kid.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <crate::Bytes>::try_from(fval)?;
                        (decoded.len() <= 8)
                            .then_some(())
                            .ok_or(MatterStatus::ConstraintError)?;
                        kid = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                _ => return Err((Some(fid), MatterStatus::ConstraintError)),
            }
        }
        Ok(Self {
            cipher_suite: cipher_suite.ok_or((Some(FieldId::new(0)), MatterStatus::ConstraintError))?,
            base_key: base_key.ok_or((Some(FieldId::new(1)), MatterStatus::ConstraintError))?,
            kid: kid.ok_or((Some(FieldId::new(2)), MatterStatus::ConstraintError))?,
        })
    }

    pub(crate) fn encode_fields_inner(self) -> Vec<(FieldId, AttributeValue)> {
        alloc::vec![
            (Self::FIELD_CIPHER_SUITE, AttributeValue::from(self.cipher_suite)),
            (Self::FIELD_BASE_KEY, AttributeValue::from(self.base_key)),
            (Self::FIELD_KID, AttributeValue::from(self.kid)),
        ]
    }
}

